def solv(n, a, b):
	curr_val = 1
	while True:
		if curr_val > n:
			return 'No'
		if (n - curr_val) % b == 0:
			return 'Yes'
		if a == 1:
			return 'No'
		curr_val = curr_val * a
t = int(input())
for i in range(0, t):
	(n, a, b) = input().split()
	print(solv(int(n), int(a), int(b)))
